rm -f .write-test
cat > backup.js <<'EOF'
const fs = require('fs');
const path = require('path');

const workspace = __dirname;
const manifestPath = path.join(workspace, 'backup-manifest.json');

const files = fs
  .readdirSync(workspace, { withFileTypes: true })
  .filter((entry) => entry.isFile())
  .map((entry) => entry.name)
  .filter((name) => !name.startsWith('.'))
  .filter((name) => name !== 'backup-manifest.json')
  .sort();

fs.writeFileSync(manifestPath, JSON.stringify({ files }, null, 2) + '\n');

console.log(`Wrote ${files.length} file(s) to ${manifestPath}`);
EOF
node backup.js && cat backup-manifest.json
